import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { shake } from "@/registry/erbium/lib/shake";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import { useRef, useState } from "react";

export default function CheckboxForm() {
  const [submitted, setSubmitted] = useState<string>();
  const [termsInvalid, setTermsInvalid] = useState(false);
  const termsInputRef = useRef<HTMLInputElement>(null);
  const termsRowRef = useRef<HTMLDivElement>(null);

  return (
    <form
      className="flex w-72 flex-col gap-4"
      onInvalid={(event) => {
        if (event.target === termsInputRef.current) {
          setTermsInvalid(true);
          shake(termsRowRef.current);
        }
      }}
      onSubmit={(event) => {
        event.preventDefault();
        const data = Object.fromEntries(new FormData(event.currentTarget));
        setSubmitted(JSON.stringify(data, null, 2));
      }}
    >
      <Field ref={termsRowRef} orientation="horizontal" invalid={termsInvalid}>
        <Checkbox
          name="terms"
          required
          inputRef={termsInputRef}
          onCheckedChange={(checked) => {
            if (checked) {
              setTermsInvalid(false);
            }
          }}
        />
        <FieldLabel>Accept terms and conditions</FieldLabel>
      </Field>
      <Field orientation="horizontal">
        <Checkbox name="newsletter" value="weekly" uncheckedValue="none" />
        <FieldLabel>Weekly newsletter</FieldLabel>
      </Field>
      <StatefulButton className="self-start" type="submit">
        Submit
      </StatefulButton>
      {submitted ? <pre className="rounded-md bg-muted p-3 text-xs">{submitted}</pre> : null}
    </form>
  );
}

import { Checkbox, CheckboxGroup } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { useState } from "react";

const permissions = [
  { id: "read", label: "Read" },
  { id: "write", label: "Write" },
  { id: "delete", label: "Delete" },
];

export default function CheckboxIndeterminate() {
  const [selected, setSelected] = useState<string[]>(["read"]);

  return (
    <CheckboxGroup
      aria-labelledby="permissions-all-label"
      allValues={permissions.map((permission) => permission.id)}
      value={selected}
      onValueChange={setSelected}
    >
      <Field orientation="horizontal">
        <Checkbox id="permissions-all" parent />
        <FieldLabel id="permissions-all-label" htmlFor="permissions-all">
          All permissions
        </FieldLabel>
      </Field>
      {permissions.map((permission) => (
        <Field orientation="horizontal" className="ps-6" key={permission.id}>
          <Checkbox id={`permissions-${permission.id}`} value={permission.id} />
          <FieldLabel className="font-normal" htmlFor={`permissions-${permission.id}`}>
            {permission.label}
          </FieldLabel>
        </Field>
      ))}
    </CheckboxGroup>
  );
}

